{
  "decisions": {
    "P0077R0F0019": {
      "action": "duplicate",
      "representative_fact_id": "P0078F0005",
      "corrections": [],
      "reason": "승인 후보 P0078F0005·P0078F0006·P0078F0007이 p78:e616 표의 세 행(평균 처리 속도, 최대 지연, 지터)을 각각 커버하며, 대상에 명시된 6개 측정값(13초, 8.8ms, 11.6ms, 118μs, 1.64ms, 47μs)이 모두 승인 근거에 포함됨. 대상의 limits에 언급된 p76:e591/p76:e593 수치(13996.40, 14400.40, 73.27, 105.84)는 제공된 원문 요소(p77~p79)에 존재하지 않는 '원문 미확인 수치'이며, 승인 후보의 limits도 '실측 결과로 확인되지는 않았다'고 동일하게 한계를 서술함. 별도 충돌 없음."
    },
    "P0077R0F0021": {
      "action": "duplicate",
      "representative_fact_id": "P0078F0008",
      "corrections": [],
      "reason": "승인 후보 P0078F0008이 p78:e617의 두 불릿(No-Pin 최대 11.6ms 스파이크, Pinned Memory DMA 셋업 비용 1~2μs 및 1.64ms 안정성)을 모두 커버하며, 대상의 관찰·측정값과 일치함. 대상의 limits에 언급된 p76:e591 Host Alloc Max Latency 13996.40μs는 제공된 원문에 없는 '원문 미확인 수치'이며, 승인 후보의 limits도 '실측 결과로 확인되지는 않았다'고 서술함. 별도 충돌 없음."
    },
    "P0077R0F0022": {
      "action": "duplicate",
      "representative_fact_id": "P0078F0009",
      "corrections": [],
      "reason": "승인 후보 P0078F0009가 p78:e619 단락의 결론(1.4%, 11.6ms, 1.64ms, 60% 이상 안정화, Pinned Memory 도입 필수적)을 모두 커버하며, 대상의 4개 측정값과 일치함. 대상의 limits에 언급된 118·47은 p78:e616 표 값으로 승인 후보가 이미 포함하고, 105.84·73.27은 제공된 원문에 없는 '원문 미확인 수치'임. '60% 이상 안정화'가 118 vs 47에서 계산된 해석값이라는 대상의 설명도 승인 후보의 limits('설명값이며 실측 미확인')와 모순되지 않음. 별도 충돌 없음."
    },
    "P0077R0F0023": {
      "action": "duplicate",
      "representative_fact_id": "P0078F0010",
      "corrections": [],
      "reason": "승인 후보 P0078F0010이 p78:e620의 평가 문장('오히려 이 현상을 정확히 짚어내고 이유를 분석하면 하드웨어와 OS 동작 메커니즘을 완벽하게 이해하고 있음을 보여주는 매우 훌륭한 학술적 분석 내용이 됩니다!')과 정확히 일치함. 대상의 limits도 '실측 결과나 객관적 평가가 아니다'라고 서술하여 승인 후보와 일치. 별도 충돌 없음."
    }
  }
}
